definidos = {r["name"]: r for r in config["resources"]}
usados = [definidos[n] for n in qpu.split(",") if n in definidos]
env = {"SLURM_JOB_QPU_RESOURCES": ",".join(r["name"] for r in usados),
       "SLURM_JOB_QPU_TYPES": ",".join(r["type"] for r in usados)}
for r in usados:
    for variable, valor in r["environment"].items():
        env[f"{r['name']}_{variable}"] = valor
return env
